select set_config('lumiscore.catalog_release_receipt','{"rows":[{"key":{"work_id":987113001,"language":"nl"},"seq":1,"relation":"catalog_work_descriptions","after_row":{"text":"Schilder Maris Coppoolse bereikt met een grote overzichtstentoonstelling een hoogtepunt in zijn loopbaan. Dan verschijnt een artikel over een misdaad die hij als veertienjarige beging. Voor de mensen om hem heen komt die geschiedenis onverwacht en zijn zorgvuldig opgebouwde bestaan raakt uit evenwicht. Maris wordt gedwongen opnieuw naar zijn verleden en zijn werk te kijken. De roman onderzoekt hoe schuld een leven kan begeleiden en wat er verandert wanneer een verborgen gebeurtenis openbaar wordt.","work_id":987113001,"evidence":[{"note":"Oek de Jong is the credited author on Atlas Contact’s exact hardback ISBN9789025451400. KB identifies the same title/ISBN author as Oebele Klaas Anne de Jong, person p068848633/Q7078543. The earlier OegeJan guess is withdrawn. Preserve existing Work/author; no person merge.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p422396249","http://data.bibliotheken.nl/id/nbt/p430163223","http://data.bibliotheken.nl/id/nbt/p424291673"],"reference":"work:1398","checked_at":"2026-11-02T21:06:36.091Z","canonical_name_resolution":"Oek de Jong is the credited author on Atlas Contact’s exact hardback ISBN9789025451400. KB identifies the same title/ISBN author as Oebele Klaas Anne de Jong, person p068848633/Q7078543. The earlier OegeJan guess is withdrawn. Preserve existing Work/author; no person merge."},{"type":"original_substantive_source_review","review":"content-review-015.json","sources":["https://www.atlascontact.nl/boek/zwarte-schuur-hardback/","https://openlibrary.org/works/OL30816328W","https://data.bibliotheken.nl/id/nbt/p422396249","https://data.bibliotheken.nl/id/nbt/p430163223","https://data.bibliotheken.nl/id/nbt/p424291673"]},{"type":"cover_front_review","sha256":"fdfeb788cfc00a31d2ce7afac9d4fe87c965f2b5d7f5b3d0f7