f0f82f43","cover_id":13748037,"reference":"cover-semantic-review-002.json","limitation":"Front and source-edition binding; no barcode or exact-printing-year assertion."}],"cover_url":"https://covers.openlibrary.org/b/id/13748037-L.jpg?default=false","edition_id":987213001,"bound_title":"Zwarte schuur","reviewed_at":"2026-11-02T21:06:36.091+00:00","bound_isbn13":"9789025451400","evidence_url":"https://data.bibliotheken.nl/id/nbt/p422396249","review_batch":"nl-scale-20261102-014","review_status":"approved","bound_language":"dut","card_cover_url":"https://covers.openlibrary.org/b/id/13748037-M.jpg?default=false","bound_author_id":987313004},"before_row":null},{"key":{"work_id":987113002,"language":"nl"},"seq":3,"relation":"catalog_work_descriptions","after_row":{"text":"Rosa en haar vrienden Esther en Jonas zijn volwassen geworden, maar weten niet altijd hoe ze hun leven moeten vormgeven. Ervaringen die groot en verwarrend voelen, blijven soms onuitgesproken. Daardoor raken ze zowel zichzelf als elkaar uit het oog. Rosa besluit dat er iets moet veranderen. Het verhaal volgt hun zoektocht naar contact, vertrouwen en een andere richting. De vertrouwde vrienden keren terug in een levensfase waarin zelfstandigheid niet vanzelf betekent dat je alles alleen kunt oplossen.","work_id":987113002,"evidence":[{"note":"KB person p084696214/Q2346051 exactly matches cached selected source person OL371169A/Q2346051. Francine is the public author credit; Eclaire Francine Marie is the authority name. Exact2023ISBN9789021475899 is separate from publisher’s current2025ISBN9789062225866; do not replace the exact edition with that current offer. Annet Schaap illustrates, not a second primary writer.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p438606698"],"reference":"work:1551","checked_at":"2026-11-02T21:06:36.091Z","canonical_name_resolution":"KB person p084696214/Q2346051 exactly matches cached selected source person OL371169A/Q2346051. Francine is the public author credit; Eclaire Francine Marie is the authority name. Exact2023ISBN9789021475899 is separate from publisher’s current2025ISBN9789062225866; do not replace the exact edition with that current offer. Annet Schaap illustrates, not a second primary writer."},{"type":"original_substantive_source_review","review":"content-review-015.json","sources":["https://www.singeluitgeverijen.nl/volt/boek/hoe-overleef-ik-alles-wat-ik-niemand-vertel/","https://openlibrary.org/works/OL36883768W","https://data.bibliotheken.nl/id/nbt/p438606698"]},{"type":"cover_front_review","sha256":"9d54afb205acc1c19c1c2181a8e83c4d95273cfc439d23d1d2489ef27e0331f4","cover_id":14534359,"reference":"cover-semantic-review-002.json","limitation":"Front and source-edition binding; no barcode or exact-printing-year assertion."}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://www.singeluitgeverijen.nl/volt/boek/hoe-overleef-ik-alles-wat-ik-niemand-vertel/","reviewed_at":"2026-11-02T21:06:36.091+00:00","source_name":"Gecontroleerde boek- en catalogusbronnen","source_type":"official_catalog","review_batch":"nl-scale-20261102-014","review_status":"approved","bound_author_id":987313003},"before_row":null},{"key":{"edition_id":987213002},"seq":4,"relation":"catalog_edition_metadata","after_row":{"format":"hardcover","work_id":987113002,"evidence":[{"note":"KB person p084696214/Q2346051 exactly matches cached selected source person OL371169A/Q2346051. Francine is the public author credit; Eclaire Francine Marie is the authority name. Exact2023ISBN9789021475899 is separate from publisher’s current2025ISBN9789062225866; do not replace the exact edition with that current offer. Annet Schaap illustrates, not a second primary writer.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p438606698"],"reference":"work:1551","checked_at":"2026-11-02T21:06:36.091Z","canonical_name_resolution":"KB person p084696214/Q2346051 exactly matches cached selected source person OL371169A/Q2346051. Francine is the public author credit; Eclaire Francine Marie is the authority name. Exact2023ISBN9789021475899 is separate from publisher’s current2025ISBN9789062225866; do not replace the exact edition with that current offer. Annet Schaap illustrates, not a second primary writer."},{"type":"original_substantive_source_review","review":"content-review-015.json","sources":["https://www.singeluitgeverijen.nl/volt/boek/hoe-overleef-ik-alles-wat-ik-niemand-vertel/","https://openlibrary.org/works/OL36883768W","https://data.bibliotheken.nl/id/nbt/p438606698"]},{"type":"cover_front_review","sha256":"9d54afb205acc1c19c1c2181a8e83c4d95273cfc439d23d1d2489ef27e0331f4","cover_id":14534359,"reference":"cover-semantic-review-002.json","limitation":"Front and source-edition binding; no barcode or exact-printing-year assertion."}],"cover_url":"https://covers.openlibrary.org/b/id/14534359-L.jpg?default=false","edition_id":987213002,"bound_title":"Hoe overleef ik alles wat ik niemand vertel?","reviewed_at":"2026-11-02T21:06:36.091+00:00","bound_isbn13":"9789021475899","evidence_url":"https://data.bibliotheken.nl/id/nbt/p438606698","review_batch":"nl-scale-20261102-014","review_status":"approved","bound_language":"dut","card_cover_url":"https://covers.openlibrary.org/b/id/14534359-M.jpg?default=false","bound_author_id":987313003},"before_row":null},{"key":{"work_id":987113003,"language":"nl"},"seq":5,"relation":"catalog_work_descriptions","after_row":{"text":"Arts Eddy de Wind beschrijft zijn ervaringen als Joodse gevangene in Auschwitz. Zijn relaas begint bij de omstandigheden die hem en zijn vrouw Friedel vanuit Westerbork naar het vernietigingskamp voerden. Hij kijkt naar het dagelijks bestaan, de voortdurende dreiging en het gedrag van mensen onder extreme druk. Persoonlijke gebeurtenissen worden verbonden met nauwkeurige observaties. Het boek legt vast hoe hij die werkelijkheid beleefde en probeerde te begrijpen, vanuit zijn positie als arts en gevangene.","work_id":987113003,"evidence":[{"note":"Exact KB ISBN9789029093606 person p06852725X explicitly lists Wind,Eddy de and Wind,Eliazar de as aliases of Eduard de Wind. Donner exact2020NLhardback confirms public Eddy credit and same camp memoir. No new author or Work.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p422983578"],"reference":"work:1619","checked_at":"2026-11-02T21:06:36.091Z","canonical_name_resolution":"Exact KB ISBN9789029093606 person p06852725X explicitly lists Wind,Eddy de and Wind,Eliazar de as aliases of Eduard de Wind. Donner exact2020NLhardback confirms public Eddy credit and same camp memoir. No new author or Work."},{"type":"original_substantive_source_review","review":"content-review-016.json","sources":["https://www.donner.nl/producten/eindstation-auschwitz-9789029093606/","https://openlibrary.org/works/OL34311013W","https://data.bibliotheken.nl/id/nbt/p422983578"]},{"type":"cover_front_review","sha256":"b70a4a064c52f230854fc63af4c5ab95988b0cd2041d435df06c37d360023fd4","cover_id":13188943,"reference":"cover-semantic-review-002.json","limitation":"Front and source-edition binding; no barcode or exact-printing-year assertion."}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://www.donner.nl/producten/eindstation-auschwitz-9789029093606/","reviewed_at":"2026-11-02T21:06:36.091+00:00","source_name":"Gecontroleerde boek- en catalogusbronnen","source_type":"official_catalog","review_batch":"nl-scale-20261102-014","review_status":"approved","bound_author_id":987313005},"before_row":null},{"key":{"edition_id":987213003},"seq":6,"relation":"catalog_edition_metadata","after_row":{"format":"hardcover","work_id":987113003,"evidence":[{"note":"Exact KB ISBN9789029093606 person p06852725X explicitly lists Wind,Eddy de and Wind,Eliazar de as aliases of Eduard de Wind. Donner exact2020NLhardback confirms public Eddy credit and same camp memoir. No new author or Work.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p422983578"],"reference":"work:1619","checked_at":"2026-11-02T21:06:36.091Z","canonical_name_resolution":"Exact KB ISBN9789029093606 person p06852725X explicitly lists Wind,Eddy de and Wind,Eliazar de as aliases of Eduard de Wind. Donner exact2020NLhardback confirms public Eddy credit and same camp memoir. No new author or Work."},{"type":"original_substantive_source_review","review":"content-review-016.json","sources":["https://www.donner.nl/producten/eindstation-auschwitz-9789029093606/","https://openlibrary.org/works/OL34311013W","https://data.bibliotheken.nl/id/nbt/p422983578"]},{"type":"cover_front_review","sha256":"b70a4a064c52f230854fc63af4c5ab95988b0cd2041d435df06c37d360023fd4","cover_id":13188943,"reference":"cover-semantic-review-002.json","limitation":"Front and source-edition binding; no barcode or exact-printing-year assertion."}],"cover_url":"https://covers.openlibrary.org/b/id/13188943-L.jpg?default=false","edition_id":987213003,"bound_title":"Eindstation Auschwitz","reviewed_at":"2026-11-02T21:06:36.091+00:00","bound_isbn13":"9789029093606","evidence_url":"https://data.bibliotheken.nl/id/nbt/p422983578","review_batch":"nl-scale-20261102-014","review_status":"approved","bound_language":"dut","card_cover_url":"https://covers.openlibrary.org/b/id/13188943-M.jpg?default=false","bound_author_id":987313005},"before_row":null},{"key":{"work_id":987113007,"language":"nl"},"seq":7,"relation":"catalog_work_descriptions","after_row":{"text":"Harry Haller voelt zich een buitenstaander in een samenleving waarvan de genoegens hem weinig zeggen. Zijn eenzaamheid en innerlijke verdeeldheid brengen hem steeds verder van anderen af. Een onverwachte ontmoeting opent mogelijkheden die hij eerder niet voor zichzelf zag. Hij wordt uitgedaagd anders om te gaan met plezier, contact en zijn eigen tegenstrijdigheden. Hermann Hesse volgt een man die zijn identiteit als afzonderlijke, lijdende geest ter discussie moet stellen zonder daar een eenvoudig antwoord op te vinden.","work_id":987113007,"evidence":[{"note":"Hermann Hesse source person OL76437A and exact-ISBN KB authority p068404956 share Wikidata Q25973, ISNI0000000121296240 and VIAF41841418. This resolves Hermann/Hermann Karl without name-only matching. Exact DeSteppewolf paperback9789023411239; existing Work retained.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p078216117","http://data.bibliotheken.nl/id/nbt/p085356573","http://data.bibliotheken.nl/id/nbt/p371614406","http://data.bibliotheken.nl/id/nbt/p830736387","http://data.bibliotheken.nl/id/nbt/p841089167"],"reference":"work:5208","checked_at":"2026-11-02T21:06:36.091Z","canonical_name_resolution":"Hermann Hesse source person OL76437A and exact-ISBN KB authority p068404956 share Wikidata Q25973, ISNI0000000121296240 and VIAF41841418. This resolves Hermann/Hermann Karl without name-only matching. Exact DeSteppewolf paperback9789023411239; existing Work retained."},{"type":"original_substantive_source_review","review":"content-review-020.json","sources":["https://openlibrary.org/works/OL872773W","https://data.bibliotheken.nl/id/nbt/p078216117","https://data.bibliotheken.nl/id/nbt/p085356573","https://data.bibliotheken.nl/id/nbt/p371614406","https://data.bibliotheken.nl/id/nbt/p830736387","https://data.bibliotheken.nl/id/nbt/p841089167"]},{"type":"cover_front_review","sha256":"7f45914a09af1bbb71c532861b731a363cae9c7384b66e12b2b4c504d6715705","cover_id":6868165,"reference":"cover-semantic-review-010.json","limitation":"Actually read cover-large/sheet-003.jpg. Hermann Hesse; De steppewolf. Front identity and source-edition attachment are corroboration, not proof of a visible barcode, printing year, language or complete contents. Bibliographic checks remain separate."}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://openlibrary.org/works/OL872773W","reviewed_at":"2026-11-02T21:06:36.091+00:00","source_name":"Gecontroleerde boek- en catalogusbronnen","source_type":"official_catalog","review_batch":"nl-scale-20261102-014","review_status":"approved","bound_author_id":987313002},"before_row":null},{"key":{"edition_id":987213008},"seq":8,"relation":"catalog_edition_metadata","after_row":{"format":"paperback","work_id":987113007,"evidence":[{"note":"Hermann Hesse source person OL76437A and exact-ISBN KB authority p068404956 share Wikidata Q25973, ISNI0000000121296240 and VIAF41841418. This resolves Hermann/Hermann Karl without name-only matching. Exact DeSteppewolf paperback9789023411239; existing Work retained.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p078216117","http://data.bibliotheken.nl/id/nbt/p085356573","http://data.bibliotheken.nl/id/nbt/p371614406","http://data.bibliotheken.nl/id/nbt/p830736387","http://data.bibliotheken.nl/id/nbt/p841089167"],"reference":"work:5208","checked_at":"2026-11-02T21:06:36.091Z","canonical_name_resolution":"Hermann Hesse source person OL76437A and exact-ISBN KB authority p068404956 share Wikidata Q25973, ISNI0000000121296240 and VIAF41841418. This resolves Hermann/Hermann Karl without name-only matching. Exact DeSteppewolf paperback9789023411239; existing Work retained."},{"type":"original_substantive_source_review","review":"content-review-020.json","sources":["https://openlibrary.org/works/OL872773W","https://data.bibliotheken.nl/id/nbt/p078216117","https://data.bibliotheken.nl/id/nbt/p085356573","https://data.bibliotheken.nl/id/nbt/p371614406","https://data.bibliotheken.nl/id/nbt/p830736387","https://data.bibliotheken.nl/id/nbt/p841089167"]},{"type":"cover_front_review","sha256":"7f45914a09af1bbb71c532861b731a363cae9c7384b66e12b2b4c504d6715705","cover_id":6868165,"reference":"cover-semantic-review-010.json","limitation":"Actually read cover-large/sheet-003.jpg. Hermann Hesse; De steppewolf. Front identity and source-edition attachment are corroboration, not proof of a visible barcode, printing year, language or complete contents. Bibliographic checks remain separate."}],"cover_url":"https://covers.openlibrary.org/b/id/6868165-L.jpg?default=false","edition_id":987213008,"bound_title":"De Steppewolf","reviewed_at":"2026-11-02T21:06:36.091+00:00","bound_isbn13":"9789023411239","evidence_url":"https://data.bibliotheken.nl/id/nbt/p078216117","review_batch":"nl-scale-20261102-014","review_status":"approved","bound_language":"dut","card_cover_url":"https://covers.openlibrary.org/b/id/6868165-M.jpg?default=false","bound_author_id":987313002},"before_row":null},{"key":{"work_id":987113005,"language":"nl"},"seq":9,"relation":"catalog_work_descriptions","after_row":{"text":"Hoe kan het heelal zijn ontstaan en wat bedoelen we wanneer we spreken over werkelijkheid? Het grote ontwerp verkent die vragen aan de hand van natuurkundige modellen. Daarbij komen onder meer verschillende mogelijke heelallen, de rol van waarneming en pogingen tot een overkoepelende theorie aan bod. De auteurs bespreken wat zulke benaderingen kunnen betekenen voor traditionele verklaringen van de kosmos. Het boek presenteert hun kijk op deze wetenschappelijke en filosofische vraagstukken, zonder dat de lezer zelf de wiskundige uitwerking hoeft te volgen.","work_id":987113005,"evidence":[{"note":"Same TheGrandDesign non-fiction Work. Primary publisher explicitly credits Stephen Hawking and Leonard Mlodinow, not a synthetic combined person. Exact Dutch paperback9789035131873 is independently bound by KB p327944463. Scientific models remain attributed to the book, no automatically approved taste features.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p327944463"],"reference":"work:2399","checked_at":"2026-11-02T21:06:36.091Z","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-review-022.json","sources":["h